/** Identifiers are opaque strings generated by the engine; the domain never creates them. */
export type Id = string;
/** Milliseconds since the Unix epoch. */
export type Timestamp = number;

export type LegalForm = "SASU" | "SAS" | "EURL" | "SARL" | "EI" | "micro";

/**
 * Where the company stands. Stages only move forward and are decided by `policy.ts`
 * from what actually happened (deliverables, fulfilled obligations), never by the player.
 */
export type Stage = "idea" | "research" | "creation" | "launch" | "operating";
export const STAGES: readonly Stage[] = ["idea", "research", "creation", "launch", "operating"];

export type RoleId =
  | "cofondateur"
  | "recherche"
  | "juridique"
  | "prospection"
  | "redaction"
  | "video"
  | "comptable"
  | "support";

export interface Founder {
  name: string;
  email?: string;
}

export interface Company {
  id: Id;
  name: string;
  idea: string;
  founder: Founder;
  city?: string;
  legalForm?: LegalForm;
  foundedAt: Timestamp;
  stage: Stage;
  paused: boolean;
}

/** Beta(success + 1, failure + 1) posterior of how reliably an agent delivers. */
export interface Skill {
  success: number;
  failure: number;
}

export interface Agent {
  id: Id;
  name: string;
  role: RoleId;
  hiredAt: Timestamp;
  status: "idle" | "working";
  currentTaskId?: Id;
  skill: Skill;
  /** 1 = everything external waits for the cancel window; 4 = trusted. Earned, never bought. */
  autonomy: 1 | 2 | 3 | 4;
}

/**
 * - `internal`: reversible work inside the company (research, drafts). Runs at its time.
 * - `external`: touches the outside world (send, publish, pay, file). Waits for the cancel window.
 * - `founder`: the law requires the founder to act (sign, verify identity). Never run by an agent.
 */
export type TaskKind = "internal" | "external" | "founder";
export type TaskStatus = "planned" | "running" | "done" | "failed" | "cancelled";

export interface Task {
  id: Id;
  agentId: Id;
  title: string;
  /** Why the agent decided to do it, in the agent's words. Shown everywhere. */
  why: string;
  kind: TaskKind;
  status: TaskStatus;
  /** Machine tag that policies reason about, e.g. "market-study", "statuts". */
  tag?: string;
  createdAt: Timestamp;
  scheduledAt: Timestamp;
  /** For external tasks: the founder can cancel until then. */
  cancellableUntil?: Timestamp;
  startedAt?: Timestamp;
  endedAt?: Timestamp;
  progress?: string;
  deliverableId?: Id;
  parentId?: Id;
  error?: string;
}

export interface Source {
  title: string;
  url?: string;
  /** ISO date the source was checked (R-SOURCE). */
  checkedAt?: string;
}

export interface Deliverable {
  id: Id;
  taskId: Id;
  agentId: Id;
  title: string;
  summary: string;
  /** Markdown. */
  body: string;
  sources: Source[];
  createdAt: Timestamp;
}

export type PostKind = "update" | "deliverable" | "hire" | "plan" | "legal";

/** A message in the Fil: an agent speaking in the first person about its work. */
export interface Post {
  id: Id;
  agentId: Id;
  at: Timestamp;
  kind: PostKind;
  text: string;
  taskId?: Id;
  deliverableId?: Id;
}

export type ObligationOwner = "founder" | RoleId;

export interface Obligation {
  id: Id;
  /** Code from the legal checklist in `obligations.ts`, e.g. "B5-signer-statuts". */
  code: string;
  title: string;
  why: string;
  owner: ObligationOwner;
  status: "open" | "done";
  openedAt: Timestamp;
  due?: Timestamp;
  doneAt?: Timestamp;
  legalBasis?: string;
}

export interface Settings {
  /** Hours the founder has to cancel an external action before it runs. */
  cancelWindowHours: number;
  maxPurchaseEur: number;
  monthlyCapEur: number;
  /** Topics the team must always run by the founder (task tags). */
  alwaysAsk: string[];
  /** How many agents may work at the same time. */
  concurrency: number;
}

export const DEFAULT_SETTINGS: Settings = {
  cancelWindowHours: 24,
  maxPurchaseEur: 100,
  monthlyCapEur: 300,
  alwaysAsk: ["prix", "publicite-payante"],
  concurrency: 3,
};

export interface Usage {
  inputTokens: number;
  outputTokens: number;
  cacheReadTokens: number;
  credits: number;
}

export interface CompanyState {
  company?: Company;
  agents: Record<Id, Agent>;
  tasks: Record<Id, Task>;
  deliverables: Record<Id, Deliverable>;
  posts: Post[];
  obligations: Record<Id, Obligation>;
  settings: Settings;
  usage: Usage;
  /** L1 core memory: the shared company sheet every agent reads (kept short). */
  memory: string;
  lastSeq: number;
}
